public final class ProductionRequests{private ProductionRequests(){}@Schema(name="ProductionCreateRequest")public record Create(@NotNull Long parcelaCultivoId,@NotNull Long visitaTecnicaId,@NotNull Instant fechaEstimacion,@NotNull LocalDate disponibleDesde,@NotNull LocalDate disponibleHasta,@NotNull@Positive BigDecimal cantidadEstimadaKg,@Size(max=400)String observacion){}@Schema(name="ProductionUpdateRequest")public record Update(@NotNull LocalDate disponibleDesde,@NotNull LocalDate disponibleHasta,@NotNull@Positive BigDecimal cantidadEstimadaKg,@Size(max=400)String observacion){}@Schema(name="ProductionDiscardRequest")public record Discard(@NotBlank@Size(max=500)String motivo){} }
